        </tbody>
      </table>
      <table data-testid="summary-periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periodRows.map(({ period: p, due, change }) => (
            <tr key={p.name} data-testid={`summary-period-${p.name}`}>
