            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-void-reasons">
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map((r) => (
            <tr key={r.reason} data-testid={`summary-void-${r.reason}`}>
              <td>{r.reason}</td>
